CREATE TABLE IF NOT EXISTS provider_directory (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider_key text NOT NULL, display_name text NOT NULL, category text NOT NULL, official_name text, complaint_route text, official_url text, grievance_contact text, supported_methods jsonb NOT NULL DEFAULT '[]'::jsonb, issue_types jsonb NOT NULL DEFAULT '[]'::jsonb, evidence_requirements jsonb NOT NULL DEFAULT '[]'::jsonb, escalation_rules jsonb NOT NULL DEFAULT '{}'::jsonb, source_url text NOT NULL, source_checked_at timestamptz NOT NULL DEFAULT now(), active boolean NOT NULL DEFAULT true, updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS provider_directory_key ON provider_directory(provider_key);
CREATE INDEX IF NOT EXISTS provider_directory_category_idx ON provider_directory(category,active);

